(function (global) {
  class Chart {
    constructor(canvas, config) {
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.config = config;
      this.render();
    }
    render() {
      const c = this.canvas,
        ctx = this.ctx,
        dpr = global.devicePixelRatio || 1,
        w = c.clientWidth || 640,
        h = c.clientHeight || 280;
      c.width = w * dpr;
      c.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      const ACCENT = "#00a887";
      const MUTED = "#8a92a3";
      const RULE = "rgba(13,15,18,0.10)";
      const INK = "#0d0f12";
      const INK3 = "#4a5168";
      const SURFACE = "#f5f7fa";

      const data = this.config.data || {},
        labels = data.labels || [],
        sets = data.datasets || [],
        max = Math.max(1, ...sets.flatMap((s) => s.data || [])) * 1.15;

      ctx.font = "500 13px 'DM Mono', monospace";
      const longestLabel = labels.reduce(
        (maxWidth, label) => Math.max(maxWidth, ctx.measureText(label).width),
        0,
      );
      const pad = {
        l: Math.min(Math.max(longestLabel + 18, 110), w * 0.42),
        r: 60,
        t: 16,
        b: 40,
      };
      const plotW = w - pad.l - pad.r,
        plotH = h - pad.t - pad.b;

      /* Grid lines */
      const ticks = 4;
      ctx.strokeStyle = RULE;
      ctx.lineWidth = 1;
      for (let i = 0; i <= ticks; i++) {
        const x = pad.l + (plotW / ticks) * i;
        ctx.beginPath();
        ctx.moveTo(x, pad.t);
        ctx.lineTo(x, pad.t + plotH);
        ctx.stroke();
      }

      ctx.font = "500 13px 'DM Mono', monospace";
      ctx.textBaseline = "middle";

      labels.forEach((label, i) => {
        const rowH = plotH / labels.length,
          y = pad.t + i * rowH + rowH / 2,
          bh = Math.min(20, rowH * 0.42);

        ctx.fillStyle = INK3;
        ctx.textAlign = "right";
        ctx.fillText(label, pad.l - 14, y);

        sets.forEach((set) => {
          const val = set.data[i] || 0,
            x = pad.l,
            barW = plotW * (val / max);

          /* Bar with gradient */
          const grad = ctx.createLinearGradient(x, 0, x + barW, 0);
          grad.addColorStop(0, ACCENT);
          grad.addColorStop(1, "rgba(0,168,135,0.4)");
          roundRect(ctx, x, y - bh / 2, barW, bh, 2, grad);

          ctx.fillStyle = INK3;
          ctx.textAlign = "left";
          ctx.fillText(String(val), x + barW + 8, y);
        });
      });

      /* Axis */
      ctx.strokeStyle = RULE;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad.l, pad.t);
      ctx.lineTo(pad.l, pad.t + plotH);
      ctx.stroke();

      ctx.fillStyle = MUTED;
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      ctx.font = "500 11px 'DM Mono', monospace";
      ctx.fillText(
        (this.config.options?.plugins?.title?.text || "").toUpperCase(),
        w / 2,
        h - 8,
      );
    }
  }

  function roundRect(ctx, x, y, w, h, r, fill) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  global.Chart = Chart;
})(window);
